from typing import List

class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()

        def best_starting_at_left() -> int:
            ans = 0
            total = 0
            j = 0

            for i, (l, r, c) in enumerate(coins):
                end = l + k - 1

                while j < len(coins) and coins[j][1] <= end:
                    total += (coins[j][1] - coins[j][0] + 1) * coins[j][2]
                    j += 1

                cur = total
                if j < len(coins) and coins[j][0] <= end:
                    cur += (end - coins[j][0] + 1) * coins[j][2]

                ans = max(ans, cur)

                if j > i:
                    total -= (r - l + 1) * c
                else:
                    j = i + 1

            return ans

        ans = best_starting_at_left()

        max_coord = max(r for _, r, _ in coins)
        reversed_coins = []
        for l, r, c in coins:
            reversed_coins.append([max_coord - r + 1, max_coord - l + 1, c])

        coins = sorted(reversed_coins)
        ans = max(ans, best_starting_at_left())

        return ans
